# Pseudo-código MapReduce
class Mapper:
  def map(key, value):
    for word in value.split():
      emit(word, 1)

class Reducer:
  def reduce(key, values):
    emit(key, sum(values))

# Ejecución:
# Map: archivo → (word, 1)
# Shuffle: agrupa (word, [1,1,1,...])
# Reduce: suma valores por palabra
